/**
 * Grain, and the drifting field behind it.
 *
 * ── WHAT THIS IS FOR ────────────────────────────────────────────────────────
 *
 * Literal noise. A film-grain layer over the whole page, which is the oldest
 * trick in editorial print and the one thing that stops a flat cream surface
 * reading as a screenshot of a wireframe. It is generated by an SVG turbulence
 * filter rather than shipped as a tiling PNG: no download, no seams, and the
 * density is a number in this file rather than a decision baked into an asset.
 *
 * Underneath it, soft fields of the product colours drift. They carry no
 * information, which is why they are aria-hidden and sit behind everything at
 * a low opacity: the job is to give the page depth and movement, not to say
 * anything.
 *
 * Both are suppressed under prefers-reduced-motion, where the drift stops and
 * only the static grain remains. Grain is texture, not motion, so it stays.
 */

/** The page-wide grain. Rendered once, fixed, and never repainted. */
export function Grain() {
  return (
    <div
      aria-hidden
      className="pointer-events-none fixed inset-0 z-[60] opacity-[0.055] mix-blend-multiply"
      style={{ contain: "strict" }}
    >
      <svg width="100%" height="100%">
        <filter id="gradlly-grain">
          {/* Fractal noise rather than turbulence: it is finer and reads as
              paper rather than as static. */}
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.82"
            numOctaves="4"
            stitchTiles="stitch"
          />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter="url(#gradlly-grain)" />
      </svg>
    </div>
  );
}

/**
 * A field of drifting colour behind a section.
 *
 * Two or three soft shapes in the product colours, heavily blurred, moving
 * slowly on independent paths so the composition never repeats a position a
 * reader will notice. Transform only, so it cannot move the layout.
 */
export function Field({ tone = "olive", density = "normal", className = "" }) {
  const palette =
    tone === "terracotta"
      ? [
          "var(--color-terracotta)",
          "var(--color-coral)",
          "var(--color-chartreuse)",
        ]
      : tone === "mixed"
        ? [
            "var(--color-olive)",
            "var(--color-terracotta)",
            "var(--color-chartreuse)",
          ]
        : [
            "var(--color-olive)",
            "var(--color-chartreuse)",
            "var(--color-olive)",
          ];

  const strength =
    density === "strong" ? 0.22 : density === "soft" ? 0.08 : 0.14;

  return (
    <div
      aria-hidden
      className={`pointer-events-none absolute inset-0 -z-10 overflow-hidden ${className}`}
    >
      <span
        className="drift drift-a absolute block rounded-full blur-[100px]"
        style={{
          background: palette[0],
          opacity: strength,
          width: "34rem",
          height: "34rem",
          insetInlineStart: "-8rem",
          insetBlockStart: "-6rem",
        }}
      />
      <span
        className="drift drift-b absolute block rounded-full blur-[110px]"
        style={{
          background: palette[1],
          opacity: strength * 0.8,
          width: "26rem",
          height: "26rem",
          insetInlineEnd: "-5rem",
          insetBlockStart: "18%",
        }}
      />
      <span
        className="drift drift-c absolute block rounded-full blur-[90px]"
        style={{
          background: palette[2],
          opacity: strength * 0.7,
          width: "20rem",
          height: "20rem",
          insetInlineStart: "38%",
          insetBlockEnd: "-6rem",
        }}
      />
    </div>
  );
}
